// Loads the WebAssembly application generated by wasm-bindgen.
import init from "/pkg/notekpr_web.js";

init({ module_or_path: "/pkg/notekpr_web_bg.wasm" }).catch((e) => {
  const el = document.getElementById("boot") || document.body;
  el.textContent = "Failed to start notekpr: " + e;
  console.error(e);
});
